export interface ServerError {
  message?: string
  details?: Details
}

export interface Details {
  applicationError?: ApplicationError
  validationError?: ValidationError
}
export interface ApplicationError {
  code?: string
  description?: string
  data?: { [key: string]: any }
}

export type ViolatedRuleType =
  | 'MIN_LENGTH'
  | 'MAX_LENGTH'
  | 'MIN_VALUE'
  | 'MAX_VALUE'
  | 'FORMAT'
  | 'REQUIRED'
  | 'OTHER'

export type RuleName =
  | 'PATTERN'
  | 'ENUM'
  | 'COLOR_FORMAT'
  | 'DATE_FORMAT'
  | 'TIME_FORMAT'
  | 'DATETIME_FORMAT'
  | string

export interface ViolationData {
  threshold?: number
  pattern?: string
  value?: string
  allowedValues?: string[]
  type?: string
  [key: string]: unknown
}

export interface FieldViolation {
  field?: string
  description?: string
  violatedRule?: ViolatedRuleType
  ruleName?: RuleName
  data?: ViolationData
}

export interface ValidationError {
  fieldViolations?: FieldViolation[]
}
